import{_ as s,o as a,c as i,a2 as t}from"./chunks/framework.BEUshCVJ.js";const u=JSON.parse('{"title":"Install MeetCue","description":"","frontmatter":{},"headers":[],"relativePath":"install.md","filePath":"install.md","lastUpdated":1792982537000}'),l={name:"install.md"};function n(o,e,r,p,h,d){return a(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="install-meetcue" tabindex="-1">Install MeetCue <a class="header-anchor" href="#install-meetcue" aria-label="Permalink to &quot;Install MeetCue&quot;">​</a></h1><p>This page shows how to install, update and remove MeetCue on Windows. The whole process works without administrator rights.</p><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><ul><li>Windows 10 version 2004 or later, or Windows 11, 64-bit.</li><li>The Microsoft Edge WebView2 runtime. It is already installed on almost every Windows 10 and 11 computer. If MeetCue reports <a href="/meetcue/troubleshooting/error-codes#mc-sys-001">MC-SYS-001</a>, install the Evergreen runtime from Microsoft.</li><li>An API key for a speech recognition provider and one for a language model provider. See <a href="/meetcue/guide/providers">Providers and keys</a>.</li></ul><div class="info custom-block"><p class="custom-block-title">macOS and Linux</p><p>MeetCue builds on macOS and Linux, but audio capture is only available on Windows in this release.</p></div><h2 id="install-with-scoop" tabindex="-1">Install with Scoop <a class="header-anchor" href="#install-with-scoop" aria-label="Permalink to &quot;Install with Scoop&quot;">​</a></h2><ol><li><p>If you don&#39;t have Scoop yet, open PowerShell and install it:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Set-ExecutionPolicy</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ExecutionPolicy RemoteSigned </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Scope CurrentUser</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">irm get.scoop.sh </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> iex</span></span></code></pre></div></li><li><p>Add the MeetCue bucket:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">scoop bucket add meetcue https:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">//</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">github.com</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Amazingkenneth</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">meetcue</span></span></code></pre></div></li><li><p>Install MeetCue:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">scoop install meetcue</span></span></code></pre></div></li><li><p>Start <strong>MeetCue</strong> from the Start menu. The first-run setup opens; continue with <a href="/meetcue/setup">First-time setup</a>.</p></li></ol><h2 id="update" tabindex="-1">Update <a class="header-anchor" href="#update" aria-label="Permalink to &quot;Update&quot;">​</a></h2><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">scoop update meetcue</span></span></code></pre></div><p>Your settings, latency history and practice records are kept in Scoop&#39;s <code>persist</code> folder, and API keys stay in Windows Credential Manager, so updates keep everything.</p><h2 id="uninstall" tabindex="-1">Uninstall <a class="header-anchor" href="#uninstall" aria-label="Permalink to &quot;Uninstall&quot;">​</a></h2><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">scoop uninstall meetcue</span></span></code></pre></div><p>To also remove your settings, add <code>--purge</code>. API keys remain in Windows Credential Manager under entries named <code>MeetCue</code>; remove them there if you want.</p><h2 id="if-something-goes-wrong" tabindex="-1">If something goes wrong <a class="header-anchor" href="#if-something-goes-wrong" aria-label="Permalink to &quot;If something goes wrong&quot;">​</a></h2><p>See <a href="/meetcue/troubleshooting/install">Install and upgrade troubleshooting</a>.</p>`,15)])])}const k=s(l,[["render",n]]);export{u as __pageData,k as default};
